package store

import (
	"context"
	"github.com/aws/aws-sdk-go-v2/aws"
	"github.com/aws/aws-sdk-go-v2/service/dynamodb"
)

func QueryOrders(ctx context.Context, c *dynamodb.Client) {
	c.Query(ctx, &dynamodb.QueryInput{TableName: aws.String("orders")})
}

func HandleRequest(ctx context.Context, c *dynamodb.Client) {
	QueryOrders(ctx, c)
}

